{"claims": [
  {
    "claim_id": "c1",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 0 states that the query planner relies on statistical information gathered by ANALYZE.",
    "citations": [
      {
        "index": 0,
        "quote": "The PostgreSQL query planner relies on statistical information about the contents of tables in order to generate good plans for queries. These statistics are gathered by the ANALYZE command"
      }
    ]
  },
  {
    "claim_id": "c2",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 0 explicitly says ANALYZE can be invoked by itself or as an optional step in VACUUM.",
    "citations": [
      {
        "index": 0,
        "quote": "which can be invoked by itself or as an optional step in VACUUM."
      }
    ]
  },
  {
    "claim_id": "c3",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 4 states that ANALYZE uses a statistically random sampling of rows rather than reading every row.",
    "citations": [
      {
        "index": 4,
        "quote": "ANALYZE uses a statistically random sampling of the rows of a table rather than reading every single row."
      }
    ]
  },
  {
    "claim_id": "c4",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 4 says it is usually best to analyze the entire database because it is fast.",
    "citations": [
      {
        "index": 4,
        "quote": "In practice, however, it is usually best to just analyze the entire database, because it is a fast operation."
      }
    ]
  },
  {
    "claim_id": "c5",
    "verdict": "UNSUPPORTED",
    "reasoning": "No passage specifies a default sample size of 30,000 rows per table for ANALYZE.",
    "citations": []
  },
  {
    "claim_id": "c6",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 1 states that the daemon schedules ANALYZE strictly as a function of the number of rows inserted or updated.",
    "citations": [
      {
        "index": 1,
        "quote": "The daemon schedules ANALYZE strictly as a function of the number of rows inserted or updated; it has no knowledge of whether that will lead to meaningful statistical changes."
      }
    ]
  },
  {
    "claim_id": "c7",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 1 shows autovacuum schedules ANALYZE only by row-count changes, so it can fail to analyze a table even when a meaningful statistical change occurs with few row changes.",
    "citations": [
      {
        "index": 1,
        "quote": "The daemon schedules ANALYZE strictly as a function of the number of rows inserted or updated; it has no knowledge of whether that will lead to meaningful statistical changes."
      }
    ]
  },
  {
    "claim_id": "c8",
    "verdict": "SUPPORTED",
    "reasoning": "Passages 2 and 6 state that changes in partitions or inheritance children do not trigger analyze/autoanalyze on the parent table.",
    "citations": [
      {
        "index": 2,
        "quote": "Tuples changed in partitions and inheritance children do not trigger analyze on the parent table."
      },
      {
        "index": 6,
        "quote": "changes to child tables do not trigger autoanalyze on the parent table."
      }
    ]
  },
  {
    "claim_id": "c9",
    "verdict": "CONTRADICTED",
    "reasoning": "Passage 6 says inheritance parents will be analyzed if the parent itself is changed, so autovacuum does not never analyze inheritance parents.",
    "citations": [
      {
        "index": 6,
        "quote": "Inheritance parents will only be analyzed if the parent itself is changed - changes to child tables do not trigger autoanalyze on the parent table."
      }
    ]
  },
  {
    "claim_id": "c10",
    "verdict": "CONTRADICTED",
    "reasoning": "Passages 6 and 7 explicitly say the autovacuum daemon does not issue ANALYZE commands for partitioned tables.",
    "citations": [
      {
        "index": 6,
        "quote": "The autovacuum daemon does not issue ANALYZE commands for partitioned tables."
      },
      {
        "index": 7,
        "quote": "autovacuum does not run ANALYZE on partitioned tables"
      }
    ]
  },
  {
    "claim_id": "c11",
    "verdict": "SUPPORTED",
    "reasoning": "Passage 3 states a timestamp column recording row update time will probably need more frequent statistics updates than a URL column.",
    "citations": [
      {
        "index": 3,
        "quote": "a timestamp column that contains the time of row update will have a constantly-increasing maximum value as rows are added and updated; such a column will probably need more frequent statistics updates than, say, a column containing URLs for pages accessed on a website."
      }
    ]
  }
]}
